CREATE TABLE members (id int PRIMARY KEY, name text NOT NULL);
CREATE TABLE books (id int PRIMARY KEY, title text NOT NULL, is_classic boolean NOT NULL);
CREATE TABLE loans (id int PRIMARY KEY, member_id int NOT NULL REFERENCES members(id), book_id int NOT NULL REFERENCES books(id));

